diff --git a/src/main/java/org/jsoup/Jsoup.java b/src/main/java/org/jsoup/Jsoup.java
index d25c1869..7e1c1ffd 100644
--- a/src/main/java/org/jsoup/Jsoup.java
+++ b/src/main/java/org/jsoup/Jsoup.java
@@ -244,10 +244,31 @@ public class Jsoup {
      @param bodyHtml HTML to test
      @param whitelist whitelist to test against
      @return true if no tags or attributes were removed; false otherwise
-     @see #clean(String, org.jsoup.safety.Whitelist) 
+     @see #clean(String, org.jsoup.safety.Whitelist)
      */
     public static boolean isValid(String bodyHtml, Whitelist whitelist) {
-        return new Cleaner(whitelist).isValid(parseBodyFragment(bodyHtml, ""));
+        // Check if input contains structural HTML tags that shouldn't be in a body fragment
+        if (bodyHtml.contains("<html") || bodyHtml.contains("<head") || bodyHtml.contains("<body")) {
+            return false;
+        }
+
+        // Check if input starts with a closing tag (malformed HTML)
+        bodyHtml = bodyHtml.trim();
+        if (bodyHtml.startsWith("</")) {
+            return false;
+        }
+
+        Document parsed = parseBodyFragment(bodyHtml, "");
+
+        // Check if HTML structure changed during parsing by checking if a clean->parse->clean cycle
+        // produces different output (indicates structural repair by the parser)
+        Document reparsed = parseBodyFragment(parsed.body().html(), "");
+        if (!parsed.body().html().equals(reparsed.body().html())) {
+            // Structure is still being modified on re-parse, indicates malformed input
+            return false;
+        }
+
+        return new Cleaner(whitelist).isValid(parsed);
     }

 }
diff --git a/src/main/java/org/jsoup/safety/Cleaner.java b/src/main/java/org/jsoup/safety/Cleaner.java
index 7e0eb28d..0d824e24 100644
--- a/src/main/java/org/jsoup/safety/Cleaner.java
+++ b/src/main/java/org/jsoup/safety/Cleaner.java
@@ -75,6 +75,11 @@ public class Cleaner {

         Document clean = Document.createShell(dirtyDocument.baseUri());
         int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
+        // Also check that the document doesn't have content in the head element
+        // since isValid should validate body HTML only, head should be empty
+        if (dirtyDocument.head() != null && dirtyDocument.head().childNodeSize() > 0) {
+            return false;
+        }
         return numDiscarded == 0;
     }
